    d = x - x.mean()
    phi = (d[:-1] @ d[1:]) / (d @ d)
    return float(len(x) * (1 - phi) / (1 + phi))


def metropolis(log_post, start, step, n, seed):
    rng = np.random.default_rng(seed)
    x = np.array(start, dtype=float)
    lp, chain, acc = log_post(x), np.empty((n, len(x))), 0
    for t in range(n):
        z, u = rng.standard_normal(len(x)), rng.uniform()
        prop = x + step * z
        lp_new = log_post(prop)
        if np.log(u) < lp_new - lp:
            x, lp, acc = prop, lp_new, acc + 1
        chain[t] = x
    return chain, acc / n


def log_post_logistic(beta, X, y, prior_sd):
    eta = X @ beta
    return float(np.sum(y * eta - np.logaddexp(0, eta)) - beta @ beta / (2 * prior_sd ** 2))


def four_chains(X, y, starts, n, step, seeds, burn):
    lp = lambda b: log_post_logistic(b, X, y, 10.0)
    return np.array([metropolis(lp, s0, step, n, sd)[0][burn:] for s0, sd in zip(starts, seeds)])


def converged(chains, tol=1.01):
    return all(split_rhat(chains[:, :, j]) < tol for j in range(chains.shape[2]))
